$lines = Get-Content -Path C:\Users\Click\.gemini\antigravity\brain\5e2595e1-3ba9-4a37-a9b1-94847181fbd2\.system_generated\logs\transcript_full.jsonl

$cmdList = @()
for ($i = 0; $i -lt $lines.Count; $i++) {
    $obj = $lines[$i] | ConvertFrom-Json
    if ($obj.tool_calls) {
        foreach ($tc in $obj.tool_calls) {
            $cmd = $tc.args.CommandLine
            if (-not $cmd) { $cmd = "$($tc.name) $($tc.args.Action) $($tc.args.TaskId) $($tc.args.AbsolutePath)" }
            # find corresponding result step
            $exitCode = "UNKNOWN"
            $endTs = "UNKNOWN"
            for ($j = $i + 1; $j -lt [Math]::Min($i + 5, $lines.Count); $j++) {
                $resObj = $lines[$j] | ConvertFrom-Json
                if ($resObj.source -in @("MODEL", "SYSTEM") -and $resObj.type -in @("GENERIC", "SYSTEM_MESSAGE")) {
                    $endTs = $resObj.created_at
                    if ($resObj.content -match "exited with code (\d+)") {
                        $exitCode = $matches[1]
                    } elseif ($resObj.content -match "finished with result:\s+The command exited with code (\d+)") {
                        $exitCode = $matches[1]
                    } elseif ($resObj.status -eq "DONE") {
                        $exitCode = "0"
                    }
                    break
                }
            }
            $cmdList += [ordered]@{
                step = $obj.step_index
                start_utc = $obj.created_at
                end_utc = $endTs
                exit = $exitCode
                command = $cmd
            }
        }
    }
}

$cmdList | ConvertTo-Json -Depth 2 | Set-Content -Encoding utf8 "artifacts\disclosure\raw-commands.json"
Write-Host "Extracted $($cmdList.Count) executed commands."
